function ResultCard({ label, value, unit = '', icon, color, isDark }) { const colorMap = { blue:{bg:'bg-blue-500/10',border:'border-blue-500/30',text:'text-blue-500',icon:'text-blue-500'}, yellow:{bg:'bg-yellow-500/10',border:'border-yellow-500/30',text:'text-yellow-500',icon:'text-yellow-500'}, orange:{bg:'bg-orange-500/10',border:'border-orange-500/30',text:'text-orange-500',icon:'text-orange-500'}, green:{bg:'bg-green-500/10',border:'border-green-500/30',text:'text-green-500',icon:'text-green-500'}, emerald:{bg:'bg-emerald-500/10',border:'border-emerald-500/30',text:'text-emerald-500',icon:'text-emerald-500'}, purple:{bg:'bg-purple-500/10',border:'border-purple-500/30',text:'text-purple-500',icon:'text-purple-500'}, red:{bg:'bg-red-500/10',border:'border-red-500/30',text:'text-red-500',icon:'text-red-500'} }; const c=colorMap[color]||colorMap.blue; return (<div className={`flex items-center justify-between p-3 rounded-lg border ${c.bg} ${c.border}`}><div className="flex items-center gap-2 min-w-0"><div className={c.icon} aria-hidden="true">{icon}</div><span className={`text-xs sm:text-sm truncate ${isDark?'text-gray-300':'text-gray-600'}`}>{label}</span></div><span className={`font-bold text-base sm:text-lg flex-shrink-0 ml-2 ${c.text}`}>{value}{unit}</span></div>); }